#include "vcc/ui/EmbeddedMusicFont.h"

#include <cstddef>

// Generated by JUCE from resources/fonts/Bravura at build time
// (ui/juce/CMakeLists.txt). The names are the files' with the dot replaced.
#include "VccMusicFontData.h"

namespace vcc::ui {

MusicFontLoad load_embedded_music_font(MusicFont& font, engraving::GlyphTable& table)
{
    const juce::String metadata = juce::String::fromUTF8(
        vcc_music_font_data::bravura_metadata_json,
        vcc_music_font_data::bravura_metadata_jsonSize);
    return font.load_from_memory(vcc_music_font_data::Bravura_otf,
                                 static_cast<std::size_t>(vcc_music_font_data::Bravura_otfSize),
                                 metadata, table);
}

const char* embedded_music_font_name() noexcept
{
    return "Bravura";
}

std::size_t embedded_music_font_size() noexcept
{
    return static_cast<std::size_t>(vcc_music_font_data::Bravura_otfSize);
}

std::string embedded_music_font_bytes()
{
    return std::string(vcc_music_font_data::Bravura_otf,
                       static_cast<std::size_t>(vcc_music_font_data::Bravura_otfSize));
}

}  // namespace vcc::ui
